```go
package forth

import (
	"errors"
	"strconv"
	"strings"
)

type tok struct {
	n    int
	name string
}

func Forth(input []string) ([]int, error) {
	words := map[string][]tok{}
	stack := []int{}

	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			// definition
			name := strings.ToLower(tokens[1])
			if _, err := strconv.Atoi(name); err == nil {
				return nil, errors.New("illegal operation")
			}
			body, err := compile(tokens[2:], words)
			if err != nil {
				return nil, err
			}
			words[name] = body
			continue
		}
		body, err := compile(tokens, words)
		if err != nil {
			return nil, err
		}
		if err := execute(body, stack); err != nil {
			return nil, err
		}
	}
	return stack, nil
}

func compile(tokens []string, words map[string][]tok) ([]tok, error) {
	body := make([]tok, 0, len(tokens))
	for _, s := range tokens {
		if n, err := strconv.Atoi(s); err == nil {
			body = append(body, tok{n: n})
			continue
		}
		name := strings.ToLower(s)
		if _, ok := words[name]; ok {
			body = append(body, tok{name: name})
			continue
		}
		body = append(body, tok{name: name}) // built-in or unknown
	}
	return body, nil
}
```

