func (f *forthVM) execWord(name string) error {
	switch name {
	case "dup":
		if len(f.stack) < 1 { return errors.New("empty stack") }
		f.stack = append(f.stack, f.stack[len(f.stack)-1])
	case "drop":
		if len(f.stack) < 1 { return errors.New("empty stack") }
		f.stack = f.stack[:len(f.stack)-1]
	case "swap":
		if len(f.stack) < 2 { return errors.New("only one value on the stack") }
		n := len(f.stack)
		f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
	case "over":
		if len(f.stack) < 2 { return errors.New("only one value on the stack") }
		f.stack = append(f.stack, f.stack[len(f.stack)-2])
	case "+", "-", "*", "/":
		if len(f.stack) < 2 { return errors.New("only one value on the stack") }
		b := f.stack[len(f.stack)-1]; a := f.stack[len(f.stack)-2]
		f.stack = f.stack[:len(f.stack)-2]
		switch name {
		case "+": f.stack = append(f.stack, a+b)
		case "-": f.stack = append(f.stack, a-b)
		case "*": f.stack = append(f.stack, a*b)
		case "/":
			if b == 0 { return errors.New("divide by zero") }
			f.stack = append(f.stack, a/b)
		}
	default:
		return errors.New("undefined operation")
	}
	return nil
}
