package forth

import (
	"errors"
	"strconv"
	"strings"
)

// tok is a compiled token: either a number to push, a built-in word to run,
// or an inlined body of a user-defined word.
type tok struct {
	n    int
	name string // built-in word name (or unknown word, to be rejected at execution)
	body []tok  // inlined body of a user-defined word
}

type forthVM struct {
	words map[string][]tok
	stack []int
}

// Forth evaluates a sequence of Forth lines and returns the final stack.
func Forth(input []string) ([]int, error) {
	f := &forthVM{
		words: map[string][]tok{},
		stack: []int{},
	}
	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			if err := f.define(tokens); err != nil {
				return nil, err
			}
			continue
		}
		body, err := f.compile(tokens)
		if err != nil {
			return nil, err
		}
		if err := f.execute(body); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

// define parses and compiles a ": name ... ;" definition.
func (f *forthVM) define(tokens []string) error {
	if len(tokens) < 3 {
		return errors.New("illegal operation")
	}
	name := strings.ToLower(tokens[1])
	if _, err := strconv.Atoi(name); err == nil {
		return errors.New("illegal operation")
	}
	end := -1
	for i, t := range tokens {
		if t == ";" {
			end = i
			break
		}
	}
	if end == -1 {
		return errors.New("illegal operation")
	}
	body, err := f.compile(tokens[2:end])
	if err != nil {
		return err
	}
	f.words[name] = body
	return nil
}

// compile resolves each token against the words known at this point,
// inlining the bodies of user-defined words so that later redefinitions
// do not affect previously compiled definitions.
func (f *forthVM) compile(tokens []string) ([]tok, error) {
	body := make([]tok, 0, len(tokens))
	for _, s := range tokens {
		if n, err := strconv.Atoi(s); err == nil {
			body = append(body, tok{n: n})
			continue
		}
		name := strings.ToLower(s)
		if def, ok := f.words[name]; ok {
			body = append(body, tok{body: def})
			continue
		}
		body = append(body, tok{name: name})
	}
	return body, nil
}

func (f *forthVM) execute(body []tok) error {
	for _, t := range body {
		switch {
		case t.body != nil:
			if err := f.execute(t.body); err != nil {
				return err
			}
		case t.name != "":
			if err := f.execWord(t.name); err != nil {
				return err
			}
		default:
			f.stack = append(f.stack, t.n)
		}
	}
	return nil
}

func (f *forthVM) execWord(name string) error {
	switch name {
	case "dup":
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		f.stack = append(f.stack, f.stack[len(f.stack)-1])
	case "drop":
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		f.stack = f.stack[:len(f.stack)-1]
	case "swap":
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		if len(f.stack) < 2 {
			return errors.New("only one value on the stack")
		}
		n := len(f.stack)
		f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
	case "over":
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		if len(f.stack) < 2 {
			return errors.New("only one value on the stack")
		}
		f.stack = append(f.stack, f.stack[len(f.stack)-2])
	case "+", "-", "*", "/":
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		if len(f.stack) < 2 {
			return errors.New("only one value on the stack")
		}
		b := f.stack[len(f.stack)-1]
		a := f.stack[len(f.stack)-2]
		f.stack = f.stack[:len(f.stack)-2]
		switch name {
		case "+":
			f.stack = append(f.stack, a+b)
		case "-":
			f.stack = append(f.stack, a-b)
		case "*":
			f.stack = append(f.stack, a*b)
		case "/":
			if b == 0 {
				return errors.New("divide by zero")
			}
			f.stack = append(f.stack, a/b)
		}
	default:
		return errors.New("undefined operation")
	}
	return nil
}
